"use client";
import { useState } from "react";
import { useRouter } from "next/navigation";
import { Menu, X, ChevronDown, ChevronUp } from "lucide-react"; 

const menuItems = [
  { name: "Buy" },
  { name: "Rent" },
  { name: "Sell" },
  {
    name: "Compass Exclusives",
    hasDropdown: true,
    subItems: ["Luxury Homes", "New Listings"],
  },
  {
    name: "New Development",
    hasDropdown: true,
    subItems: ["Upcoming Projects", "Investment Properties"],
  },
  {
    name: "Agents",
    hasDropdown: true,
    subItems: ["Find an Agent", "Join Compass"],
  },
];

const Navbar = () => {
  const router = useRouter();
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [openDropdown, setOpenDropdown] = useState<string | null>(null);

  const toggleDropdown = (itemName: string) => {
    setOpenDropdown(openDropdown === itemName ? null : itemName);
  };

  return (
    <nav className="flex items-center justify-between  px-6 py-4 font-semibold shadow-md bg-opacity-50 text-black relative z-50">
      <div className="flex items-center space-x-4">
        <div className="lg:hidden cursor-pointer" onClick={() => setIsMenuOpen(true)}>
          <Menu className="w-6 h-6 text-white" />
        </div>

        <div className="text-xl font-bold cursor-pointer text-white" onClick={() => router.push("/")}>
          AVACASA
        </div>
      </div>

      {/* Desktop Navigation (Hidden on mobile) */}
      <div className="hidden lg:flex space-x-6">
        {menuItems.map((item) => (
          <div key={item.name} className="relative group cursor-pointer">
            <button    onClick={() =>toggleDropdown(item.name)} className="hover:text-blue-500 flex items-center text-white">
              {item.name} 
              {item.hasDropdown &&
                    (openDropdown === item.name ? (
                      <ChevronUp className="w-5 h-5" />
                    ) : (
                      <ChevronDown className="w-5 h-5" />
                    ))}
            </button>
            {item.hasDropdown && openDropdown === item.name && (
              <div className="absolute left-0 mt-2 w-48 bg-white text-black shadow-md rounded-md hidden lg:block ">
                {item.subItems?.map((subItem) => (
                  <div key={subItem} className="px-4 py-2 hover:bg-gray-100 cursor-pointer">
                    {subItem}
                  </div>
                ))}
              </div>
            )}
          </div>
        ))}
      </div>
      <button
        onClick={() => router.push("/login")}
        className="text-white hover:text-blue-500"
      >
        Register/Sign In
      </button>

      {/* Full-Screen Sidebar (Mobile Menu) */}
      {isMenuOpen && (
        <div className="fixed top-0 left-0 w-9/12 md:w-5/12 h-full text-black bg-white shadow-lg z-50 flex flex-col p-6">
          {/* Close Button */}
          <div className="flex justify-between items-center">
            <div className="text-xl font-bold">AVACASA</div>
            <X className="w-6 h-6 cursor-pointer" onClick={() => setIsMenuOpen(false)} />
          </div>

          {/* Mobile Menu Items */}
          <div className="flex-grow mt-6  space-y-4">
            {menuItems.map((item) => (
              <div key={item.name}>
                <div
                  className="text-lg font-medium cursor-pointer flex justify-between items-center"
                  onClick={() => (item.hasDropdown ? toggleDropdown(item.name) : null)}
                >
                  {item.name}
                  {item.hasDropdown &&
                    (openDropdown === item.name ? (
                      <ChevronUp className="w-5 h-5" />
                    ) : (
                      <ChevronDown className="w-5 h-5" />
                    ))}
                </div>

                {/* Submenu (Dropdown for Mobile) */}
                {openDropdown === item.name && item.hasDropdown && (
                  <div className="ml-4 mt-2 space-y-2">
                    {item.subItems?.map((subItem) => (
                      <div key={subItem} className="text-black cursor-pointer hover:text-black">
                        {subItem}
                      </div>
                    ))}
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;